import serial,time,json,sys,re
S=sys.argv[1]
absent=[a for a in json.load(open(S+'/doc_absent.json')) if re.match(r'^\+[A-Z0-9]+$',a)]
extra="""CGNSPWR CGNSINF CGNSURC CGNSTST CGNSCMD CGNSSEQ CGPSSTATUS CGPSPWR CGPSURL CGPSSSL CGPSFTPEPH CGPSXE CAGPS CGPSHOT CGPSCOLD CBAND CSTT CIICR CIFSR CIPSTART CIPSHUT CIPMUX CIPHEAD CIPSRIP CIPCSGP CIPRXGET CIPSPRT CIPSCONT CIPCCFG SAPBR CNACT CNCFG CAOPEN CASEND CARECV CACLOSE CASSLCFG CMNB CBANDCFG CNETLIGHT CSGS CEXTERNTONE CTONE CDTMF CLDTMF CPMUTEMP CBATCHK CGPIO SGPIO CVAUXV CVAUXS CPLMNPASS CMEDPLAY CMEDIA CTXFREQ GCAP GOI GSV CMGEF CRIS CIND CMER CSDH CAOC CCLK CALA CALD CRSL CEER CNMA CSCB CMMS CSAS CHOLD CRSM CPOL CPLS COPN CSPN CESQ CSCON CEREG CGREG CPNVS CEMNL CRLP CBST CSNS CR CRC CHSN CMOD CVMOD CSDF CTZR CSTA CDIP CIPPING CIPDNS CDNSGIP CIPDPDP CIPCSGP CPING CNSMOD CNTP CNTPCID CNETSCAN CPSI CGMI QCRMCALL CSIMLOCK CSIMLOCKKEY CSIMLOCKD CPBF CPBW CTZUA CGDCONT CSSLCFG CCHSET CCHMODE CCHOPEN CGFUNC CGSETV CGGETV CRFSET CLEDITT CGPSXD CAOPEN CNETSTART CTCPSET SIMEI CNBP CNMP CLCC CLCCEX SIMUPDATE CUSBCFG CUSBSPD CUSBPIDSWITCH CHSET CNVF CCUSAGE UCUSAGE CIPTIMER CIPMODE CIPCLOSE CRSVD CBCINFO CRXGAIN CMICGAIN COUTGAIN CPCMFREQ CPCMBANDWIDTH CPCMREG CAUDIOMODE CTTSPARAM CTTS CAUDPATH CMEDIAVOL CSPKGAIN CLCK CGSMS CGPRS CGATT SMSTATUS CAUTH""".split()
names=sorted(set(absent)|set('+'+x for x in extra))
DENY=re.compile(r'^\+(CRESET|CPOF|CPOWD|BOOTLDR|CNV\w*|CQCNV|CMGS|CMGSEX|CMSS|CMSSEX|CMGW|CMGWEX|CSIM|CRSM|CGLA|CRLA|CSIMLOCK\w*|SIMEI|SIMUPDATE|CUSBPIDSWITCH|CUSBCFG|CUSBSPD|CQCNV|CGPSXTRADATA|CNETSCAN|COPS|CPIN|CPWD|CLCK|CHUP|CGPS|CGNSPWR|CGPSPWR|CPNVS|CTONE|CDTMF|CLDTMF|CMEDPLAY|CGPSCOLD|CGPSHOT|CRFSET|CGSETV|CGPIO|SGPIO|CIICR|CIPSTART|CIPSHUT|CIPCLOSE|CAOPEN|CACLOSE|CASEND|CCHOPEN|CNACT|CPBW|CMGD|CPOL|CSVM|CPUC|CPBF|CSTA)$')
todo=[n for n in names if not DENY.match(n)]
print(len(todo),'candidates',flush=True)
s=serial.Serial('/dev/cu.usbserial-0001',9600,timeout=0.2)
def send(c,maxw=6):
    s.reset_input_buffer(); s.write((c+'\r\n').encode()); t0=time.time(); b=b''; q=time.time()
    while time.time()-t0<maxw:
        d=s.read(500)
        if d: b+=d; q=time.time()
        t=b.rstrip()
        if (t.endswith(b'OK') or t.endswith(b'ERROR') or b'ERROR:' in t) and time.time()-q>0.15: break
    return b.decode(errors='replace').replace('\r','').strip()
out=[]
for n in todo:
    out.append({'cmd':n,'test':send('AT'+n+'=?'),'read':send('AT'+n+'?')})
json.dump(out,open(S+'/discover.json','w'))
print('done')
